"""Export standalone pytest-playwright tests and execute fix-flip validation."""

from __future__ import annotations

from proofqa.contracts import Action, ActionKind, Finding, WorldSpec


def generate_pytest_test(
    finding: Finding,
    repro_actions: list[Action],
    test_name: str = "test_reproduction",
) -> str:
    """Generate a clean, standalone pytest-playwright test file string from a minimal repro."""
    lines = [
        '"""Exported standalone regression test generated by ProofQA."""',
        "",
        "import pytest",
        "from playwright.async_api import Page",
        "",
        "@pytest.mark.asyncio",
        f"async def {test_name}(page: Page, base_url: str) -> None:",
        '    """Asserts that the system does NOT exhibit the target defect."""',
        "    observed_5xx = []",
        "    page.on('response', lambda res: observed_5xx.append(res.status) if res.status >= 500 else None)",
        "",
    ]

    for act in repro_actions:
        if act.kind == ActionKind.GOTO:
            target = act.value or "/"
            lines.append(f'    await page.goto(f"{{base_url}}{target}", wait_until="domcontentloaded")')
        elif act.kind == ActionKind.CLICK and act.locator:
            if act.locator.role and act.locator.name:
                lines.append(f'    await page.get_by_role("{act.locator.role}", name="{act.locator.name}").click()')
            elif act.locator.label:
                lines.append(f'    await page.get_by_label("{act.locator.label}").click()')
            elif act.locator.testid:
                lines.append(f'    await page.get_by_test_id("{act.locator.testid}").click()')
            elif act.locator.css_fallback:
                lines.append(f'    await page.locator("{act.locator.css_fallback}").click()')
        elif act.kind == ActionKind.FILL and act.locator:
            val = act.value or ""
            if act.locator.role and act.locator.name:
                lines.append(f'    await page.get_by_role("{act.locator.role}", name="{act.locator.name}").fill("{val}")')
            elif act.locator.label:
                lines.append(f'    await page.get_by_label("{act.locator.label}").fill("{val}")')
            elif act.locator.testid:
                lines.append(f'    await page.get_by_test_id("{act.locator.testid}").fill("{val}")')
            elif act.locator.css_fallback:
                lines.append(f'    await page.locator("{act.locator.css_fallback}").fill("{val}")')

    lines.extend([
        "    await page.wait_for_timeout(500)",
        "    # Invariant: No first-party 5xx responses observed",
        "    assert len(observed_5xx) == 0, f'Expected 0 5xx responses, found {observed_5xx}'",
        "",
    ])

    return "\n".join(lines)


async def validate_fix_flip(
    finding: Finding,
    repro_actions: list[Action],
    world_spec: WorldSpec,
) -> bool:
    """Fix-Flip Validator:

    Runs the generated reproduction against:
    1. Buggy world -> Must FAIL (bug exhibits).
    2. Fixed/Clean world -> Must PASS (bug absent).
    Returns True only if both conditions hold.
    """
    from proofqa.proof.replay import replay

    # 1. Buggy world check
    buggy_rep = await replay(repro_actions, world_spec, n=1, target_signature=finding.signature)
    if buggy_rep.fail_count == 0:
        return False

    # 2. Fixed/Clean world check (remove the bug)
    clean_spec = WorldSpec(app_id=world_spec.app, bugs=[b for b in world_spec.bugs if b not in finding.signature.error_type])
    clean_rep = await replay(repro_actions, clean_spec, n=1, target_signature=finding.signature)
    if clean_rep.fail_count > 0:
        return False

    return True
